use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let mut result = Vec::new();
        let mut current = String::new();
        let mut count = 0;

        for c in s.chars() {
            if c == current.chars().next().unwrap() {
                count += 1;
            } else {
                result.push(Value::Array(vec![Value::String(current), Value::Integer(count)]));
                current = String::new();
                count = 1;
            }
        }

        result.push(Value::Array(vec![Value::String(current), Value::Integer(count)]));
        Value::Array(result)
    } else {
        Value::Array(vec![])
    }
}
